import { test, describe } from 'node:test'
import assert from 'node:assert/strict'
import { RATING_SCALE, notchChange } from '../../src/ratings/notch.mjs'

describe('RATING_SCALE', () => {
  test('AC-1: RATING_SCALE has correct values and is frozen', () => {
    const expected = [
      'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
      'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-',
      'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-'
    ]
    assert.deepStrictEqual(RATING_SCALE, expected)
    assert.strictEqual(RATING_SCALE.length, 19)
    assert.strictEqual(Object.isFrozen(RATING_SCALE), true)

    // Verify frozen: push should throw
    assert.throws(
      () => RATING_SCALE.push('CC'),
      TypeError
    )
    assert.strictEqual(RATING_SCALE.length, 19)
  })
})

describe('Module exports', () => {
  test('AC-2: Correct named exports, no default export', async () => {
    const m = await import('../../src/ratings/notch.mjs')
    const keys = Object.keys(m).sort()
    assert.deepStrictEqual(keys, ['RATING_SCALE', 'notchChange'])
    assert.strictEqual(m.default, undefined)
    assert.strictEqual(typeof m.notchChange, 'function')
  })
})

describe('notchChange basic functionality', () => {
  test('AC-3: Downgrade BBB+ to BB+ returns 3', () => {
    assert.strictEqual(notchChange('BBB+', 'BB+'), 3)
  })

  test('AC-4: Upgrade BB+ to BBB+ returns -3', () => {
    assert.strictEqual(notchChange('BB+', 'BBB+'), -3)
  })

  test('AC-5: No change returns 0 for all 19 ratings', () => {
    for (const rating of RATING_SCALE) {
      assert.strictEqual(notchChange(rating, rating), 0)
    }
  })
})

describe('notchChange all pairs and spot values', () => {
  test('AC-6: All 361 pairs follow formula and antisymmetry', () => {
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        const result = notchChange(p, c)
        const expected = RATING_SCALE.indexOf(c) - RATING_SCALE.indexOf(p)

        assert.strictEqual(result, expected, `notchChange('${p}','${c}')`)
        assert.strictEqual(Number.isInteger(result), true)

        // Check antisymmetry
        const reverse = notchChange(c, p)
        assert.strictEqual(reverse, -result)
      }
    }
  })

  test('AC-6: Spot values', () => {
    assert.strictEqual(notchChange('AAA', 'AA+'), 1)
    assert.strictEqual(notchChange('A-', 'BBB+'), 1)
    assert.strictEqual(notchChange('BBB-', 'BB+'), 1)
    assert.strictEqual(notchChange('B-', 'CCC+'), 1)
    assert.strictEqual(notchChange('AA', 'A'), 3)
    assert.strictEqual(notchChange('CCC', 'B+'), -4)
  })
})

describe('notchChange range and synchronicity', () => {
  test('AC-7: Min and max values', () => {
    assert.strictEqual(notchChange('AAA', 'CCC-'), 18)
    assert.strictEqual(notchChange('CCC-', 'AAA'), -18)

    // Verify all results are in range
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        const result = notchChange(p, c)
        assert.ok(result >= -18 && result <= 18)
      }
    }
  })

  test('AC-8: Result is synchronous (not Promise)', () => {
    const result = notchChange('BBB', 'BB')
    assert.strictEqual(typeof result, 'number')
    assert.strictEqual(result instanceof Promise, false)
    assert.strictEqual(typeof result.then, 'undefined')
  })
})

describe('notchChange case insensitivity', () => {
  test('AC-9: Case-insensitive matching', () => {
    assert.strictEqual(notchChange('bbb+', 'bb+'), 3)
    assert.strictEqual(notchChange('Aa-', 'aa-'), 0)
    assert.strictEqual(notchChange('ccc-', 'aaa'), -18)
  })
})

describe('notchChange whitespace handling', () => {
  test('AC-10: Trim leading/trailing whitespace', () => {
    assert.strictEqual(notchChange(' BBB+ ', '\tBB+\n'), 3)
    assert.strictEqual(notchChange(' A ', 'A'), 0)
    // BOM character (U+FEFF) should be trimmed
    assert.strictEqual(notchChange('﻿bb+ ', 'BBB+'), -3)
  })

  test('AC-11: Reject inner whitespace', () => {
    assert.throws(
      () => notchChange('BBB +', 'A'),
      RangeError
    )
    assert.throws(
      () => notchChange('A', 'B B'),
      RangeError
    )
  })
})

describe('notchChange invalid symbols', () => {
  test('AC-12: Reject unknown symbols', () => {
    const unknownSymbols = [
      'CC', 'C', 'D', 'NR', 'SD', 'Baa1',
      'AAA+', 'BBB++', 'A1', 'B--', 'CCC-+', 'AAAA', '+', '-',
      'ＡＡＡ' // full-width
    ]

    for (const symbol of unknownSymbols) {
      assert.throws(
        () => notchChange(symbol, 'A'),
        RangeError,
        `Should reject '${symbol}' as previous`
      )
      assert.throws(
        () => notchChange('A', symbol),
        RangeError,
        `Should reject '${symbol}' as current`
      )
    }
  })
})

describe('notchChange empty/whitespace strings', () => {
  test('AC-13: Reject empty or whitespace-only strings', () => {
    const emptyStrings = ['', '   ', '\t\n', '\t', '\n']

    for (const str of emptyStrings) {
      assert.throws(
        () => notchChange(str, 'A'),
        RangeError,
        `Should reject empty/whitespace '${JSON.stringify(str)}' as previous`
      )
      assert.throws(
        () => notchChange('A', str),
        RangeError,
        `Should reject empty/whitespace '${JSON.stringify(str)}' as current`
      )
    }
  })
})

describe('notchChange non-string inputs', () => {
  test('AC-14: Reject non-string inputs', () => {
    const nonStrings = [
      undefined,
      null,
      7,
      0,
      NaN,
      true,
      {},
      ['A'],
      new String('A'),
      Symbol('A'),
      () => 'A',
      7n,
      Object.create(null)
    ]

    for (const value of nonStrings) {
      assert.throws(
        () => notchChange(value, 'A'),
        RangeError,
        `Should reject non-string ${typeof value} as previous`
      )
      assert.throws(
        () => notchChange('A', value),
        RangeError,
        `Should reject non-string ${typeof value} as current`
      )
    }
  })

  test('AC-14: Missing arguments throw RangeError', () => {
    assert.throws(
      () => notchChange('A'),
      RangeError
    )
    assert.throws(
      () => notchChange(),
      RangeError
    )
  })
})

describe('notchChange error messages', () => {
  test('AC-15: Error message names the argument', () => {
    const err1 = assert.throws(
      () => notchChange('A', null),
      RangeError
    )
    assert.ok(err1.message.includes('current'))
    assert.ok(!err1.message.includes('previous'))

    const err2 = assert.throws(
      () => notchChange('XX', 'A'),
      RangeError
    )
    assert.ok(err2.message.includes('previous'))
    assert.ok(!err2.message.includes('current'))
  })

  test('AC-15: Both invalid gives error about previous', () => {
    const err = assert.throws(
      () => notchChange('XX', null),
      RangeError
    )
    assert.ok(err.message.includes('previous'))
    assert.ok(!err.message.includes('current'))
  })
})

describe('notchChange purity and module integrity', () => {
  test('AC-16: No imports or console statements in source', async () => {
    const fs = await import('node:fs')
    const source = fs.readFileSync('../../src/ratings/notch.mjs', 'utf8')

    assert.ok(!source.match(/^\s*import\s/m), 'Should have no import statements')
    assert.ok(!source.includes('console.'), 'Should have no console calls')
  })

  test('AC-16: RATING_SCALE remains frozen and unchanged after calls', () => {
    const original = [...RATING_SCALE]

    // Make various calls
    notchChange('A', 'B')
    try {
      notchChange('x', 'A')
    } catch {}

    assert.deepStrictEqual(RATING_SCALE, original)
    assert.strictEqual(Object.isFrozen(RATING_SCALE), true)
  })
})

describe('notchChange edge cases', () => {
  test('Extra arguments are ignored', () => {
    assert.strictEqual(notchChange('A', 'B', 'junk'), 9)
  })
})

// Pure function: no imports, no I/O, no side effects

const RATING_SCALE = Object.freeze([
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
  'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-',
  'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-'
])

// Build a case-insensitive lookup map for fast matching
const ratingLookup = new Map()
for (const rating of RATING_SCALE) {
  ratingLookup.set(rating.toUpperCase(), rating)
}

// Helper function to safely describe a value in an error message
function describe(value) {
  const t = typeof value
  if (t === 'string') {
    return JSON.stringify(value)
  }
  if (t === 'symbol') {
    return String(value)
  }
  if (t === 'bigint') {
    return String(value) + 'n'
  }
  if (t === 'function') {
    return 'function'
  }
  if (value === null) {
    return 'null'
  }
  if (t === 'object') {
    if (Array.isArray(value)) {
      return 'array'
    }
    return 'object'
  }
  return String(value)
}

// Helper function to validate and normalize a single rating argument
function validateRating(value, argName) {
  // Step (a): type check - only primitive strings
  if (typeof value !== 'string') {
    throw new RangeError(`Invalid ${argName} rating: received ${describe(value)}`)
  }

  // Step (b): trim
  const trimmed = value.trim()

  // Step (c) and (d): case-insensitive match
  const upper = trimmed.toUpperCase()
  if (!ratingLookup.has(upper)) {
    throw new RangeError(`Invalid ${argName} rating: received ${JSON.stringify(value)}`)
  }

  // Return the canonical rating from the scale
  return ratingLookup.get(upper)
}

// Main function: returns signed notch change
function notchChange(previous, current) {
  // Validate previous first
  const prevRating = validateRating(previous, 'previous')

  // Then validate current
  const currRating = validateRating(current, 'current')

  // Calculate the difference
  const prevIndex = RATING_SCALE.indexOf(prevRating)
  const currIndex = RATING_SCALE.indexOf(currRating)

  return currIndex - prevIndex
}

