// T-01 QA: integration tests for src/ratings/notch.mjs, through the public import only.
import { test, describe } from 'node:test'
import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { readFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import * as m from '../../../src/ratings/notch.mjs'

const { RATING_SCALE, notchChange } = m

const EXPECTED_SCALE = [
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
  'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-',
  'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
]

const here = (rel) => fileURLToPath(new URL(rel, import.meta.url))
const SRC_PATH = here('../../../src/ratings/notch.mjs')
const REPO_ROOT = here('../../../')

// Asserts the call throws exactly a RangeError (not a TypeError or any other error).
function assertRangeError(fn, label) {
  let caught
  try {
    fn()
  } catch (err) {
    caught = err
  }
  assert.ok(caught !== undefined, `${label}: expected a throw`)
  assert.ok(caught instanceof RangeError, `${label}: expected RangeError, got ${caught && caught.constructor && caught.constructor.name}`)
  assert.equal(caught.constructor, RangeError, `${label}: constructor must be RangeError`)
}

describe('T-01 notchChange (integration)', () => {
  test('AC-1: RATING_SCALE is the 19 ratings, best first, frozen and push throws TypeError', () => {
    assert.deepEqual([...RATING_SCALE], EXPECTED_SCALE)
    assert.deepEqual(RATING_SCALE, EXPECTED_SCALE)
    assert.equal(RATING_SCALE.length, 19)
    assert.equal(Object.isFrozen(RATING_SCALE), true)
    assert.throws(() => RATING_SCALE.push('CC'), TypeError)
    assert.equal(RATING_SCALE.length, 19)
  })

  test('AC-2: exactly two named exports, no default, notchChange is a function', () => {
    assert.deepEqual(Object.keys(m).sort(), ['RATING_SCALE', 'notchChange'])
    assert.equal(m.default, undefined)
    assert.equal(typeof m.notchChange, 'function')
  })

  test('AC-3: BBB+ -> BB+ is a downgrade of +3', () => {
    assert.equal(notchChange('BBB+', 'BB+'), 3)
  })

  test('AC-4: BB+ -> BBB+ is an upgrade of -3', () => {
    assert.equal(notchChange('BB+', 'BBB+'), -3)
  })

  test('AC-5: A -> A is 0, and r -> r is 0 for every rating', () => {
    assert.equal(notchChange('A', 'A'), 0)
    for (const r of RATING_SCALE) {
      assert.equal(notchChange(r, r), 0, `${r} -> ${r}`)
      assert.ok(!Object.is(notchChange(r, r), -0), `${r} -> ${r} must not be -0`)
    }
  })

  test('AC-6: all 361 pairs equal index(c) - index(p), are integers and antisymmetric', () => {
    let pairs = 0
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        pairs++
        const result = notchChange(p, c)
        assert.equal(result, RATING_SCALE.indexOf(c) - RATING_SCALE.indexOf(p), `${p} -> ${c}`)
        assert.ok(Number.isInteger(result), `${p} -> ${c} integer`)
        assert.ok(notchChange(c, p) === -result || (result === 0 && notchChange(c, p) === 0), `${c} -> ${p} antisymmetry`)
      }
    }
    assert.equal(pairs, 361)
  })

  test('AC-6: spot values', () => {
    assert.equal(notchChange('AAA', 'AA+'), 1)
    assert.equal(notchChange('A-', 'BBB+'), 1)
    assert.equal(notchChange('BBB-', 'BB+'), 1)
    assert.equal(notchChange('B-', 'CCC+'), 1)
    assert.equal(notchChange('AA', 'A'), 3)
    assert.equal(notchChange('CCC', 'B+'), -4)
  })

  test('AC-7: ends of the scale are +18 / -18 and every result is within [-18, 18]', () => {
    assert.equal(notchChange('AAA', 'CCC-'), 18)
    assert.equal(notchChange('CCC-', 'AAA'), -18)
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        const r = notchChange(p, c)
        assert.ok(r >= -18 && r <= 18, `${p} -> ${c} = ${r} out of range`)
      }
    }
  })

  test('AC-8: result is a plain number, not a Promise or thenable', () => {
    const result = notchChange('BBB', 'BB')
    assert.equal(result, 2)
    assert.equal(typeof result, 'number')
    assert.equal(result instanceof Promise, false)
    assert.equal(typeof result.then, 'undefined')
  })

  test('AC-9: case-insensitive input', () => {
    assert.equal(notchChange('bbb+', 'bb+'), 3)
    assert.equal(notchChange('Aa-', 'aa-'), 0)
    assert.equal(notchChange('ccc-', 'aaa'), -18)
  })

  test('AC-10: leading and trailing whitespace removed by trim() is accepted', () => {
    assert.equal(notchChange(' BBB+ ', '\tBB+\n'), 3)
    assert.equal(notchChange(' A ', 'A'), 0) // no-break space
    assert.equal(notchChange('﻿bb+ ', 'BBB+'), -3) // BOM is trimmed
  })

  test('AC-11: whitespace inside a rating is rejected with RangeError', () => {
    assertRangeError(() => notchChange('BBB +', 'A'), "('BBB +','A')")
    assertRangeError(() => notchChange('A', 'B B'), "('A','B B')")
  })

  test('AC-12: unknown rating symbols throw RangeError in both positions', () => {
