    delete env.NODE_TEST_CONTEXT // run the child as a fresh, top-level test run
    const res = spawnSync(process.execPath, ['--test', unitPath], { cwd: REPO_ROOT, encoding: 'utf8', env })
    assert.equal(res.status, 0, res.stdout + res.stderr)
    assert.match(res.stdout, /(# |\u2139 )fail 0/)
